import sys
sys.setrecursionlimit(300000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        if n == 2:
            results.append("1")
            continue

        parent = [0] * (n + 1)
        order = []
        stack = [1]
        visited = [False] * (n + 1)
        visited[1] = True

        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    parent[v] = u
                    stack.append(v)

        children_count = [0] * (n + 1)
        for i in range(n, 0, -1):
            if parent[i] != 0:
                children_count[parent[i]] += 1

        is_leaf = [False] * (n + 1)
        is_bud = [False] * (n + 1)

        for i in range(1, n + 1):
            if children_count[i] == 0:
                is_leaf[i] = True
            else:
                all_children_leaves = True
                for v in adj[i]:
                    if parent[v] == i and not is_leaf[v]:
                        all_children_leaves = False
                        break
                if not all_children_leaves:
                    is_bud[i] = False
                else:
                    if parent[i] != 0:
                        is_bud[i] = True
                    else:
                        is_bud[i] = False

        dp = [0] * (n + 1)

        for i in reversed(order):
            if is_leaf[i]:
                dp[i] = 1
            else:
                total_leaves = 0
                has_bud_child = False
                for v in adj[i]:
                    if parent[v] == 1 or parent[v] == i:
                        if parent[v] == i:
                            if is_bud[v]:
                                has_bud_child = True
                                total_leaves += 1
                            else:
                                total_leaves += dp[v]

                if has_bud_child:
                    dp[i] = 1
                else:
                    dp[i] = total_leaves

        results.append(str(dp[1]))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
